events.query:
 *[_type == "manufacturingStep"] | order(order asc) {
   _id,
   order,
   title,
   description,
   icon { 
 asset->{_id, url, metadata {dimensions, lqip}},
 alt,
 hotspot,
 crop
}
 }

 *[_type == "educationArticle" && defined(publishedAt)] | order(publishedAt desc) {

 _id,
 title,
 slug { current },
 summary,
 publishedAt,
 heroImage { 
 asset->{_id, url, metadata {dimensions, lqip}},
 alt,
 hotspot,
 crop
},
 category->{ name, slug { current } }

 }

 *[_type == "educationArticle" && defined(publishedAt)] | order(publishedAt desc) {

 _id,
 title,
 slug { current },
 summary,
 publishedAt,
 heroImage { 
 asset->{_id, url, metadata {dimensions, lqip}},
 alt,
 hotspot,
 crop
},
 category->{ name, slug { current } }

 }
